    parents = {}
    while to_be_evaluated:
        current = min(to_be_evaluated, key=lambda node: g_scores.get(node, float('inf')))
        if current == goal:
            path = [current]
            while current in parents:
                current = parents[current]
                path.append(current)
            return path[::-1]
        to_be_evaluated.remove(current)
        visited.add(current)
        for neighbour in graph.get(current, []):
            if neighbour in visited:
                continue
            tentative_g_score = g_scores.get(current, float('inf')) + 1
            if neighbour not in g_scores or tentative_g_score < g_scores[neighbour]:
                g_scores[neighbour] = tentative_g_score
                parents[neighbour] = current
                to_be_evaluated.add(neighbour)
    return None

