def find_path(graph, start, goal):
    unseen_nodes = list(graph.keys())
    limit_depth = 0
    ways_to_here = {}
    ancestors = {node: None for node in graph.keys()}
    to_visit = [start]
    while to_visit and limit_depth < 1000:
        node = to_visit[-1]
        if node in seen_nodes and node not in ways_to_here:
            to_visit.pop()
            continue
        if node == goal:
            break
        seen_nodes.add(node)
        for neighbor in graph[node]:
            if neighbor not in seen_nodes:
                to_visit.append(neighbor)
                ways_to_here[neighbor] = node
                ancestors[neighbor] = node
        to_visit.pop()
    path = []
    while node:
        path.append(node)
        node = ways_to_here.get(node)
    path = path[::-1]
    return path

