def find_path(graph, start, goal):
    stack = [(stack, visited, [start]) for stack, visited in dfs_iter(graph, start, set())]
    while stack:
        try:
            stack, visited, path = stack.pop()
            current = path[-1]
            if current == goal:
                return path
            for neighbor in graph.get(current, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    stack.append((stack, visited, path + [neighbor]))
        except Exception:
            pass
    return None

def dfs_iter(graph, start, visited):
    stack = [(start, [start])]
    while stack:
        current, path = stack.pop()
        visited.add(current)
        yield (stack, visited, path)
        for neighbor in graph.get(current, []):
            if neighbor not in visited:
                stack.append((neighbor, path + [neighbor]))

